style.css:
@-moz-document domain("soundcloud.com") {
/* 01 - 1619 x 971 neon city sunset embedded as JPEG data URI. */
html, body {
  background-color: #120016 !important;
}
body {
  background-image: url("data:image/jpeg;base64,") !important;
  background-position: center center !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
  min-height: 100vh !important;
  color: #FFB347 !important;
}

/* Keep app shells transparent so the image is actually visible. */
#app, #content, .l-container, .l-content, .l-main,
.l-fluid-fixed, .l-fixed-top, .l-about-main, .l-search,
.l-listen-content, .l-product-banners, .l-sidebar-right,
.sc-background-default, .sc-background-dark {
  background-color: transparent !important;
  background-image: none !important;
}

/* 02 - Header and sticky playback bar use deep, translucent plum. */
.header, .header__inner, .playControls, .playControls__inner,
.playControls__bg, .playControls__elements {
  background-color: rgba(20,7,26,0.87) !important;
  background-image: none !important;
  color: #FFAA33 !important;
  border-color: rgba(238,95,189,0.45) !important;
  box-shadow: 0 0 17px rgba(227,76,169,0.16) !important;
}

/* 03 - Panels remain readable, while still revealing the wallpaper.
   Never tint cover art, artwork image sources, avatars or thumbnails. */
.sc-background-light, .sc-background-white, .g-dark-bg,
.g-modal-section, .modal__modal, .dialog, .dropbar__content,
.moreMenu__list, .profileMenu__list, .volume__sliderWrapper,
.tabs__tabs, .tabs__headingContainer, .listenLogin,
.commentForm__wrapper, .commentFormDisabled,
.unreadConversations, .searchAutocomplete,
.searchAutocomplete__list, .sidebarModule,
.sidebarModule__content, .listenEngagement,
.sound__soundActions, .sound__mainContent,
.sound__comments, .modal, .modal.modalWhiteout {
  background-color: rgba(24,8,32,0.77) !important;
  border-color: rgba(237,94,195,0.33) !important;
  color: #FFB85C !important;
}
/* Preserve native cover art/hero images; clear framing only. */
.fullHero, .fullHero__foreground, .fullListenHero,
.fullListenHero__foreground, .sound__header, .sound__body {
  background-color: transparent !important;
}

/* 04 - Brighter readable typography.  Do not change icons via filters. */
body, #content, .l-content, .l-main,
.sc-text, .sc-text-primary, .sc-type-medium,
.sc-type-small, .sc-type-large, .commentItem__body,
.commentItem__content, .listenEngagement,
.soundBadge__title, .playbackSoundBadge__titleLink,
.playableTile__heading, .playableTile__mainHeading,
.trackItem__trackTitle, .soundTitle__title,
.commentItem__username, .sidebarModule__title,
.headerMenu__link, .profileMenu__link,
.userBadge__username, .sound__mainContent {
  color: #FFB84D !important;
}
/* Headings: near-white with a soft magenta glow. */
h1, h2, h3, h4, h5, h6,
.sc-type-h1, .sc-type-h2, .sc-type-h3, .sc-type-h4,
.sc-type-h5, .sc-type-h6, .soundTitle__title,
.sidebarModule__title, .g-headline {
  color: #FF8C00 !important;
  text-shadow: 0 0 10px rgba(255,76,199,0.38), 0 1px 3px rgba(15,0,21,0.75) !important;
}
/* Secondary labels: distinct from primary, but no longer muddy. */
.sc-text-light, .sc-text-secondary, .sc-text-hint,
.sc-type-light, .sc-type-secondary, .sc-type-caption,
.commentItem__createdAt, .commentItem__time,
.trackItem__username, .soundBadge__username,
.playbackSoundBadge__lightLink,
.playableTile__username, .userBadge__username,
.commentItem__usernameTitle, .soundTitle__usernameTitle {
  color: #B84DFF !important;
}
/* Warm ember label accents; ensure contrast on dark surfaces. */
.header__navMenu a, .sc-type-small.sc-type-light,
.sc-tag, .tabs__tab, .tabs__tab a {
  color: #FFA11A !important;
}
body p, body li, body label, body small, body time,
.commentItem__body, .commentItem__content {
  text-shadow: 0 1px 3px rgba(9,0,15,0.45);
}

/* 05 - Link colors and hover cues (original style was more muted). */
a:link, a:visited,
.sc-text-link, .sc-link-dark, .sc-link-light,
.commentItem a, .trackItem__trackTitle,
.soundTitle__usernameTitle {
  color: #FF2FD6 !important;
}
a:hover, a:focus,
.sc-text-link:hover, .commentItem a:hover,
.trackItem__trackTitle:hover, .soundTitle__title:hover,
.playbackSoundBadge__titleLink:hover {
  color: #FFD200 !important;
  text-shadow: 0 0 8px rgba(255,64,201,0.82), 0 0 16px rgba(255,128,48,0.37) !important;
}

/* 06 - Keep classic ember-orange CTA/play controls. */
.sc-button, .sc-button-cta, .sc-button-play,
.sc-tag, .dropdownContent__listItem {
  border-color: rgba(255,86,211,0.63) !important;
}
.sc-button { color: #FF38E1 !important; }
.sc-button-cta, .sc-button-play, .sc-button-primary,
.sc-button-orange {
  color: #140015 !important;
  background-color: #FF6A00 !important;
  border-color: #FFC300 !important;
  box-shadow: 0 0 14px rgba(255,110,18,0.48) !important;
}
.sc-button:hover, .sc-button:focus,
.sc-button-cta:hover, .sc-button-cta:focus,
.sc-button-play:hover, .sc-button-play:focus {
  border-color: #FFD400 !important;
  box-shadow: 0 0 0 1px rgba(255,194,64,0.78),
              0 0 16px rgba(255,120,14,0.76),
              0 0 26px rgba(255,50,192,0.59) !important;
}
.sc-button-cta:hover, .sc-button-play:hover,
.sc-button-primary:hover, .sc-button-orange:hover {
  background-color: #FF8A00 !important;
  color: #140015 !important;
}
.playControls__play, .playControls__prev, .playControls__next,
.playControls__repeat, .playControls__shuffle {
  color: #FF47E5 !important;
}
.playControls__control:hover, .playControls__control:focus,
.playControls__play:hover, .playControls__play:focus,
.playControls__next:hover, .playControls__prev:hover,
.playControls__repeat:hover, .playControls__shuffle:hover {
  color: #FFE100 !important;
  filter: drop-shadow(0 0 6px rgba(255,68,199,0.88)) !important;
}

/* 07 - Menu highlights: subdued magenta glass. */
.trackItem:hover, .compactTrackListItem.clickToPlay:hover,
.chartTrack:hover, .soundBadge:hover {
  background-color: rgba(91,16,77,0.79) !important;
  box-shadow: inset 3px 0 0 #FF00D9,
              0 0 12px rgba(255,65,193,0.42) !important;
}
.header .header__navMenu > li > a.selected,
.header .header__navMenu > li > a:hover,
.headerMenu__link:hover, .profileMenu__link:hover,
.dropdownContent__listItem:hover, .searchAutocomplete a:hover {
  color: #FFE000 !important;
  background-color: rgba(139,20,100,0.53) !important;
  text-shadow: 0 0 10px rgba(255,60,201,0.81) !important;
}

/* 08 - Readable search, comments, and form inputs. */
.headerSearch__input, input[type="search"], input[type="text"],
input[type="email"], textarea, select, .commentForm__input {
  color: #FF6BFF !important;
  background-color: rgba(26,8,36,0.91) !important;
  border-color: rgba(255,82,204,0.66) !important;
  caret-color: #FF00E6 !important;
}
input::placeholder, textarea::placeholder,
.headerSearch__input::placeholder {
  color: #B84DFF !important;
  opacity: 1 !important;
}
.headerSearch__input:hover, input[type="search"]:hover,
input[type="text"]:hover, textarea:hover {
  border-color: #FF00D9 !important;
  box-shadow: 0 0 11px rgba(255,56,202,0.40) !important;
}
.headerSearch__input:focus, input[type="search"]:focus,
input[type="text"]:focus, textarea:focus {
  border-color: #FFD400 !important;
  box-shadow: 0 0 0 1px rgba(255,199,110,0.72),
              0 0 15px rgba(255,67,198,0.55) !important;
}
.sc-tag:hover {
  border-color: #FF00D9 !important;
  box-shadow: 0 0 11px rgba(255,61,200,0.64) !important;
}

/* 09 - Preserve the original square-cover glow without transforms. */
.playableTile__artworkLink, .playableTile__artwork,
.playableTile__artwork .sc-artwork,
.playableTile__artworkLink .sc-artwork, .soundBadge__artwork,
.audibleTile__artwork, .visualSound__artwork,
.tileGallery .sc-artwork {
  transition: box-shadow 0.22s ease, outline-color 0.22s ease !important;
}
.playableTile:hover .playableTile__artworkLink,
.playableTile__artworkLink:hover, .playableTile__artworkLink:focus,
.playableTile:hover .playableTile__artwork,
.playableTile__artwork:hover,
.playableTile__artworkLink:hover .sc-artwork,
.tileGallery__sliderPanelSlide:hover .playableTile__artworkLink,
.soundBadge:hover .soundBadge__artwork,
.soundBadge__artwork:hover, .audibleTile:hover .audibleTile__artwork,
.visualSound:hover .visualSound__artwork {
  border-radius: 5px !important;
  box-shadow: 0 0 0 2px #FF00E6,
              0 0 16px rgba(255,44,200,0.85),
              0 0 29px rgba(255,113,35,0.51) !important;
}
.playableTile:hover .playableTile__heading,
.playableTile:hover .playableTile__mainHeading,
.playableTile__heading:hover {
  color: #FFE000 !important;
  text-shadow: 0 0 10px rgba(255,64,205,0.67) !important;
}

/* 10 - Selected text colors. */
::selection {
  background-color: rgba(255,55,200,0.64);
  color: #FFF06A;
}

/* 11 - Keep orange buttons readable even when link hover rules apply. */
a.sc-button-cta, a.sc-button-play, a.sc-button-primary, a.sc-button-orange,
a.sc-button-cta:hover, a.sc-button-play:hover,
a.sc-button-primary:hover, a.sc-button-orange:hover {
  color: #160012 !important;
}


/* 12 - Wallpaper palette: neon orange, hot pink, vivid violet.
   High contrast on near-black/plum panels; do not tint artwork. */
.soundTitle__title, .trackItem__trackTitle,
.playableTile__heading, .playableTile__mainHeading,
.soundBadge__title, .playbackSoundBadge__titleLink,
.sc-type-h2, .sc-type-h3 {
  color: #FF9500 !important;
  text-shadow: 0 0 7px rgba(255,88,64,0.23) !important;
}
.soundTitle__usernameTitle, .soundBadge__username,
.trackItem__username, .playableTile__username,
.userBadge__username, .commentItem__username {
  color: #FF41E1 !important;
}
.commentItem__body, .commentItem__content,
.sc-text-primary, .sc-type-medium, .sc-text {
  color: #FFB347 !important;
}
.sc-text-light, .sc-text-secondary,
.sc-text-hint, .sc-type-caption,
.commentItem__createdAt, .commentItem__time {
  color: #B84DFF !important;
}
.sc-text-link, .sc-link-light, .sc-link-dark,
.commentItem a, .tabs__tab a, .headerMenu__link,
.profileMenu__link, .header__navMenu a {
  color: #FF2FD6 !important;
}
/* High-energy hover: orange title, electric-pink rim, violet accent. */
.sc-text-link:hover, .sc-text-link:focus,
.commentItem a:hover, .commentItem a:focus,
.trackItem__trackTitle:hover, .trackItem__trackTitle:focus,
.soundTitle__title:hover, .soundTitle__title:focus,
.playbackSoundBadge__titleLink:hover,
.playableTile__heading:hover,
.soundBadge__title:hover {
  color: #FFE600 !important;
  text-shadow: 0 0 8px rgba(255,81,205,0.85),
               0 0 16px rgba(255,125,22,0.42) !important;
}
.header .header__navMenu > li > a:hover,
.header .header__navMenu > li > a.selected,
.headerMenu__link:hover, .profileMenu__link:hover,
.searchAutocomplete a:hover, .dropdownContent__listItem:hover {
  color: #FFF04A !important;
  background-color: rgba(126,16,95,0.61) !important;
  text-shadow: 0 0 10px rgba(255,72,201,0.77) !important;
  box-shadow: inset 0 -2px 0 #FF00E6 !important;
}
/* Violet labels with hot pink and amber highlights. */
.sc-tag, .tabs__tab, .tabs__tab a,
.header__navMenu a, .sc-button {
  border-color: rgba(255,77,200,0.64) !important;
}
.sc-tag:hover, .tabs__tab:hover,
.tabs__tab a:hover {
  color: #FFD16D !important;
  border-color: #FF00D9 !important;
  text-shadow: 0 0 9px rgba(255,57,201,0.70) !important;
}
.sc-button:hover, .sc-button:focus {
  color: #FFD36F !important;
  border-color: #FF00D9 !important;
}
/* Keep orange CTA/button text dark, including links on hover. */
.sc-button-cta, .sc-button-play,
.sc-button-primary, .sc-button-orange,
.sc-button-cta:hover, .sc-button-play:hover,
.sc-button-primary:hover, .sc-button-orange:hover,
a.sc-button-cta, a.sc-button-play,
a.sc-button-primary, a.sc-button-orange,
a.sc-button-cta:hover, a.sc-button-play:hover,
a.sc-button-primary:hover, a.sc-button-orange:hover {
  color: #170013 !important;
}
}
